Lemma sh_sep : forall x k y l, x mod 8 = 0 -> y mod 8 = 0 -> 0 <= k -> 0 <= l ->
  x + 8 * k <= y \/ y + 8 * l <= x -> sh x + k <= sh y \/ sh y + l <= sh x.
Proof.
